      "title": "MAPF-LNS2: Fast Repairing for Multi-Agent Path Finding via Large Neighborhood Search",
      "key_contribution": "LNS-based repair framework that starts from infeasible paths and iteratively replans subsets of colliding agents using SIPPS single-agent planner",
      "relevance": "Primary inspiration for our LNS baseline; we extend with MARL-guided neighborhood selection"
    },
    {
      "id": "paper_001", 
      "title": "PRIMAL: Pathfinding via Reinforcement and Imitation Multi-Agent Learning",
      "key_contribution": "Combines RL and imitation learning for fully-decentralized MAPF policies that scale to large team sizes",
      "relevance": "Inspires our value-function-like estimates for agent difficulty assessment"
    },
    {
      "id": "paper_002",
      "title": "SCRIMP: Scalable Communication for Reinforcement- and Imitation-Learning-Based Multi-Agent Pathfinding",
      "key_contribution": "Transformer-based communication mechanism for MARL MAPF with small FOVs",
      "relevance": "Informs our spatial congestion and local observation components in value estimation"
    },
